values ((select id from public.topics where subject_id = (select id from public.subjects where slug = 'english') and slug = 'iba-50-words'), 'The word "ANOMALY" means —', array['Willing to take bold risks; or showing a lack of respect', 'Something that is unusual or unexpected', 'To cause something to happen quickly or suddenly', 'Lacking energy and enthusiasm; sluggish']::text[], 1, 'Anomaly (নিয়ম-বহির্ভূত ব্যাপার, ব্যতিক্রম) — something that is unusual or unexpected. e.g. The student’s poor performance on the latest test was an anomaly since she had previously earned excellent grades.', 'IBA MBA ’12, ’18 · 50 Words', true);
insert into public.questions (topic_id, stem, options, correct_index, explanation, source, published)
values ((select id from public.topics where subject_id = (select id from public.subjects where slug = 'english') and slug = 'iba-50-words'), 'The word "EQUIVOCAL" means —', array['Not easily understood or explained; open to more than one interpretation', 'Likely to change rapidly and unpredictably', 'Easily bent or shaped; easily influenced; malleable', 'To support or strengthen']::text[], 0, 'Equivocal (দ্ব্যর্থক, অস্পষ্ট) — not easily understood or explained; open to more than one interpretation. e.g. Politicians have been known to provide equivocal answers to reporters’ questions.', 'IBA BBA ’15 · 50 Words', true);
insert into public.questions (topic_id, stem, options, correct_index, explanation, source, published)
values ((select id from public.topics where subject_id = (select id from public.subjects where slug = 'english') and slug = 'iba-50-words'), 'The word "LUCID" means —', array['A state of physical or mental inactivity; lethargy', 'Very clear and easy to understand', 'Likely to change rapidly and unpredictably', 'Tending to talk a great deal']::text[], 1, 'Lucid (স্পষ্ট, সুবোধ্য) — very clear and easy to understand. e.g. The lecture was lucid and straightforward, allowing the students to fully grasp the concepts presented.', 'IBA BBA ’15, ’16 · 50 Words', true);
