values ((select id from public.topics where subject_id = (select id from public.subjects where slug = 'english') and slug = 'iba-50-words'), 'The word "ASSUAGE" means —', array['To make an unpleasant feeling less intense', 'To support or strengthen', 'To waver between different opinions or actions', 'Easily bent or shaped; easily influenced; malleable']::text[], 0, 'Assuage (প্রশমিত করা, উপশম করা) — to make an unpleasant feeling less intense. e.g. A massage can assuage the soreness in your muscles.', 'IBA MBA ’11, ’13 · 50 Words', true);
