values ((select id from public.topics where subject_id = (select id from public.subjects where slug = 'english') and slug = 'iba-50-words'), 'The word "ERUDITE" means —', array['Having or showing great knowledge', 'To regard with great respect; revere', 'Using very few words', 'A speech or writing that praises someone, typically one who has recently died']::text[], 0, 'Erudite (পণ্ডিত, জ্ঞানী) — having or showing great knowledge. e.g. High school students often struggle with novels that are more erudite than they are entertaining.', 'IBA MBA ’13 · 50 Words', true);
