values ((select id from public.topics where subject_id = (select id from public.subjects where slug = 'english') and slug = 'iba-50-words'), 'The word "ENIGMA" means —', array['To persistently avoid or reject', 'Strong enthusiasm and determination to do something', 'To make someone less angry or hostile', 'A person or thing that is mysterious, puzzling, or difficult to understand']::text[], 3, 'Enigma (রহস্য, হেঁয়ালি) — a person or thing that is mysterious, puzzling, or difficult to understand. e.g. Scientists continue to research cancer to solve the enigma of its primary cause.', 'IBA MBA ’11 · 50 Words', true);
