insert into public.questions (topic_id, stem, options, correct_index, explanation, source, published)
values ((select id from public.topics where subject_id = (select id from public.subjects where slug = 'english') and slug = 'iba-50-words'), 'The word "LAUDABLE" means —', array['Easily bent or shaped; easily influenced; malleable', 'Deserving praise and commendation', 'A person or thing that is mysterious, puzzling, or difficult to understand', 'To confirm or give support to a statement or theory']::text[], 1, 'Laudable (প্রশংসনীয়) — deserving praise and commendation. e.g. Providing affordable healthcare for all citizens is a laudable goal.', 'IBA BBA ’15 · 50 Words', true);
insert into public.questions (topic_id, stem, options, correct_index, explanation, source, published)
values ((select id from public.topics where subject_id = (select id from public.subjects where slug = 'english') and slug = 'iba-50-words'), 'The word "PEDANT" means —', array['A speech or writing that praises someone, typically one who has recently died', 'Not able to be seen through; not easily understood', 'Strong enthusiasm and determination to do something', 'A person who makes an excessive display of learning or fusses over minor rules']::text[], 3, 'Pedant (বিদ্যাবাগীশ, জ্ঞান জাহির করা ব্যক্তি) — a person who makes an excessive display of learning or fusses over minor rules. e.g. Professor Blackwell, a well-known pedant, required his pre-med students to speak in Latin throughout the entire semester.', 'IBA MBA ’23 · 50 Words', true);
insert into public.questions (topic_id, stem, options, correct_index, explanation, source, published)
values ((select id from public.topics where subject_id = (select id from public.subjects where slug = 'english') and slug = 'iba-50-words'), 'The word "VACILLATE" means —', array['Dealing with problems in a practical, sensible way rather than by theory', 'To make an unpleasant feeling less intense', 'To waver between different opinions or actions', 'A pretentious or showy display, especially of wealth']::text[], 2, 'Vacillate (ইতস্তত করা, দ্বিধায় দোলা) — to waver between different opinions or actions. e.g. Undergraduate students often vacillate among various majors before deciding which degree to pursue.', 'IBA MBA ’22 · 50 Words', true);
insert into public.questions (topic_id, stem, options, correct_index, explanation, source, published)
values ((select id from public.topics where subject_id = (select id from public.subjects where slug = 'english') and slug = 'iba-50-words'), 'The word "CAPRICIOUS" means —', array['Wastefully extravagant', 'Given to sudden and unpredictable changes of mood or behavior', 'Willing to take bold risks; or showing a lack of respect', 'A pretentious or showy display, especially of wealth']::text[], 1, 'Capricious (খামখেয়ালি) — given to sudden and unpredictable changes of mood or behavior. e.g. The capricious supervisor would hand out raises one day and fire his entire staff the next.', 'IBA BBA ’11 · 50 Words', true);
insert into public.questions (topic_id, stem, options, correct_index, explanation, source, published)
values ((select id from public.topics where subject_id = (select id from public.subjects where slug = 'english') and slug = 'iba-50-words'), 'The word "HOMOGENEOUS" means —', array['To make someone less angry or hostile', 'Not able to be seen through; not easily understood', 'Of the same or similar kind', 'To regard with great respect; revere']::text[], 2, 'Homogeneous (একই রকমের, সমজাতীয়) — of the same or similar kind. e.g. There are very few truly homogeneous cultures since social diversity is increasingly widespread.', 'IBA MBA ’05 · 50 Words', true);
insert into public.questions (topic_id, stem, options, correct_index, explanation, source, published)
values ((select id from public.topics where subject_id = (select id from public.subjects where slug = 'english') and slug = 'iba-50-words'), 'The word "LOQUACIOUS" means —', array['Tending to talk a great deal', 'To go back and forth between choices or opinions; be indecisive', 'Wastefully extravagant', 'Likely to change rapidly and unpredictably']::text[], 0, 'Loquacious (বাচাল, বেশি কথা বলে এমন) — tending to talk a great deal. e.g. The loquacious professor was known for his five-hour lectures.', 'IBA MBA ’24 · 50 Words', true);
insert into public.questions (topic_id, stem, options, correct_index, explanation, source, published)
values ((select id from public.topics where subject_id = (select id from public.subjects where slug = 'english') and slug = 'iba-50-words'), 'The word "PRAGMATIC" means —', array['Dealing with problems in a practical, sensible way rather than by theory', 'A lack of harmony or agreement', 'To waver between different opinions or actions', 'To restrain oneself from doing or enjoying something']::text[], 0, 'Pragmatic (বাস্তববাদী) — dealing with problems in a practical, sensible way rather than by theory. e.g. A pragmatic approach to legislation can be difficult given the complexities of politics.', 'IBA MBA ’05, ’23 · 50 Words', true);
insert into public.questions (topic_id, stem, options, correct_index, explanation, source, published)
values ((select id from public.topics where subject_id = (select id from public.subjects where slug = 'english') and slug = 'iba-50-words'), 'The word "VOLATILE" means —', array['Willing to take bold risks; or showing a lack of respect', 'To restrain oneself from doing or enjoying something', 'To go back and forth between choices or opinions; be indecisive', 'Likely to change rapidly and unpredictably']::text[], 3, 'Volatile (অস্থির, বারবার পরিবর্তনশীল) — likely to change rapidly and unpredictably. e.g. It is possible for a country’s political climate to remain volatile for decades.', 'IBA BBA ’11 · 50 Words', true);
insert into public.questions (topic_id, stem, options, correct_index, explanation, source, published)
values ((select id from public.topics where subject_id = (select id from public.subjects where slug = 'english') and slug = 'iba-50-words'), 'The word "TORPOR" means —', array['A state of physical or mental inactivity; lethargy', 'Just begun and so not fully formed or developed', 'To regard with great respect; revere', 'Having or showing great knowledge']::text[], 0, 'Torpor (আলস্য, জড়তা) — a state of physical or mental inactivity; lethargy. e.g. The more time in the day the patient is idle, the more he is likely to sink into a torpor.', 'IBA BBA ’11 · 50 Words', true);
insert into public.questions (topic_id, stem, options, correct_index, explanation, source, published)
values ((select id from public.topics where subject_id = (select id from public.subjects where slug = 'english') and slug = 'iba-50-words'), 'The word "CORROBORATE" means —', array['To confirm or give support to a statement or theory', 'Innocent and unsuspecting; naive', 'To cause someone to feel drained of energy; weaken', 'To avoid telling the truth by not directly answering a question']::text[], 0, 'Corroborate (সমর্থন করা, প্রমাণ দিয়ে নিশ্চিত করা) — to confirm or give support to a statement or theory. e.g. The scientist was able to corroborate his hypothesis with data gathered from multiple sources.', 'IBA MBA ’16 · 50 Words', true);
insert into public.questions (topic_id, stem, options, correct_index, explanation, source, published)
values ((select id from public.topics where subject_id = (select id from public.subjects where slug = 'english') and slug = 'iba-50-words'), 'The word "EPHEMERAL" means —', array['Lasting for a very short time', 'Wastefully extravagant', 'Stubbornly refusing to change one’s opinion or course of action', 'To express contempt for; ridicule']::text[], 0, 'Ephemeral (ক্ষণস্থায়ী) — lasting for a very short time. e.g. An ephemeral moment of victory may last mere seconds, but it can remain as a triumphant memory for decades.', 'IBA MBA ’23 · 50 Words', true);
insert into public.questions (topic_id, stem, options, correct_index, explanation, source, published)
values ((select id from public.topics where subject_id = (select id from public.subjects where slug = 'english') and slug = 'iba-50-words'), 'The word "LACONIC" means —', array['Using very few words', 'A person or thing that is mysterious, puzzling, or difficult to understand', 'Not easily understood or explained; open to more than one interpretation', 'To cause someone to feel drained of energy; weaken']::text[], 0, 'Laconic (স্বল্পভাষী, সংক্ষিপ্ত) — using very few words. e.g. The student’s laconic response suggested that she did not know very much about the topic.', 'IBA MBA ’22 · 50 Words', true);
insert into public.questions (topic_id, stem, options, correct_index, explanation, source, published)
values ((select id from public.topics where subject_id = (select id from public.subjects where slug = 'english') and slug = 'iba-50-words'), 'The word "MITIGATE" means —', array['Great warmth or intensity of feeling; passion; zeal', 'To make something less severe, serious, or painful', 'Seeking to promote the welfare of others, especially by donating money', 'Easily persuaded to believe something; easily fooled']::text[], 1, 'Mitigate (প্রশমিত করা, লাঘব করা) — to make something less severe, serious, or painful. e.g. We want to mitigate students’ exam stress by offering helpful study tools.', 'IBA MBA ’06 · 50 Words', true);
insert into public.questions (topic_id, stem, options, correct_index, explanation, source, published)
values ((select id from public.topics where subject_id = (select id from public.subjects where slug = 'english') and slug = 'iba-50-words'), 'The word "PROPRIETY" means —', array['The state or quality of being correct or proper; conformity to accepted standards', 'Deserving praise and commendation', 'Excessively talkative, especially about trivial matters', 'To waver between different opinions or actions']::text[], 0, 'Propriety (শালীনতা, ঔচিত্য) — the state or quality of being correct or proper; conformity to accepted standards. e.g. The students were instructed to behave with the utmost propriety while on their class field trip.', 'IBA MBA ’22 · 50 Words', true);
insert into public.questions (topic_id, stem, options, correct_index, explanation, source, published)
values ((select id from public.topics where subject_id = (select id from public.subjects where slug = 'english') and slug = 'iba-50-words'), 'The word "INCHOATE" means —', array['Lasting for a very short time', 'To waver between different opinions or actions', 'A person or thing that is mysterious, puzzling, or difficult to understand', 'Just begun and so not fully formed or developed']::text[], 3, 'Inchoate (অঙ্কুরাবস্থার, অপরিণত) — just begun and so not fully formed or developed. e.g. She had a child’s inchoate awareness of language.', 'IBA BBA ’11 · 50 Words', true);
insert into public.questions (topic_id, stem, options, correct_index, explanation, source, published)
values ((select id from public.topics where subject_id = (select id from public.subjects where slug = 'english') and slug = 'iba-50-words'), 'The word "CACOPHONY" means —', array['A harsh, unpleasant mixture of sounds', 'Tending to talk a great deal', 'To cause someone to feel drained of energy; weaken', 'A state of physical or mental inactivity; lethargy']::text[], 0, 'Cacophony (কর্কশ, বেসুরো শব্দের মিশ্রণ) — a harsh, unpleasant mixture of sounds. e.g. The cacophony of the middle school band warming up was nearly unbearable for the audience.', 'IBA MBA ’24 · 50 Words', true);
insert into public.questions (topic_id, stem, options, correct_index, explanation, source, published)
values ((select id from public.topics where subject_id = (select id from public.subjects where slug = 'english') and slug = 'iba-50-words'), 'The word "ENERVATE" means —', array['A moment of sudden and great revelation or realization', 'A harsh, unpleasant mixture of sounds', 'To cause someone to feel drained of energy; weaken', 'Very clear and easy to understand']::text[], 2, 'Enervate (দুর্বল করে ফেলা, শক্তি নিঃশেষ করা) — to cause someone to feel drained of energy; weaken. e.g. The boxer used a swift left uppercut to the jaw to enervate his opponent.', 'IBA BBA ’21 · 50 Words', true);
insert into public.questions (topic_id, stem, options, correct_index, explanation, source, published)
values ((select id from public.topics where subject_id = (select id from public.subjects where slug = 'english') and slug = 'iba-50-words'), 'The word "INGENUOUS" means —', array['To make something less severe, serious, or painful', 'A person who makes an excessive display of learning or fusses over minor rules', 'Innocent and unsuspecting; naive', 'Stubbornly refusing to change one’s opinion or course of action']::text[], 2, 'Ingenuous (সরল, সাদাসিধা, অকপট) — innocent and unsuspecting; naive. e.g. The scam artist preyed on ingenuous nursing home residents.', 'IBA MBA ’16 · 50 Words', true);
insert into public.questions (topic_id, stem, options, correct_index, explanation, source, published)
values ((select id from public.topics where subject_id = (select id from public.subjects where slug = 'english') and slug = 'iba-50-words'), 'The word "EPIPHANY" means —', array['Great warmth or intensity of feeling; passion; zeal', 'To make an unpleasant feeling less intense', 'A moment of sudden and great revelation or realization', 'To cause someone to feel drained of energy; weaken']::text[], 2, 'Epiphany (আকস্মিক বোধোদয়, হঠাৎ উপলব্ধি) — a moment of sudden and great revelation or realization. e.g. Seeing her father again when she was an adult was an epiphany that changed her whole view of her childhood.', 'IBA BBA ’19 · 50 Words', true);
insert into public.questions (topic_id, stem, options, correct_index, explanation, source, published)
values ((select id from public.topics where subject_id = (select id from public.subjects where slug = 'english') and slug = 'iba-50-words'), 'The word "PARADOX" means —', array['Innocent and unsuspecting; naive', 'A statement that seems to contradict itself but may be true', 'Not easily understood or explained; open to more than one interpretation', 'The state or quality of being correct or proper; conformity to accepted standards']::text[], 1, 'Paradox (স্ববিরোধিতা, আপাতবিরোধী উক্তি) — a statement that seems to contradict itself but may be true. e.g. The fact that the retired teacher claimed to hate all pets but adopted seven cats is an intriguing paradox.', 'IBA MBA ’24 · 50 Words', true);
insert into public.questions (topic_id, stem, options, correct_index, explanation, source, published)
values ((select id from public.topics where subject_id = (select id from public.subjects where slug = 'english') and slug = 'iba-50-words'), 'The word "VENERATE" means —', array['To regard with great respect; revere', 'A person or thing that is mysterious, puzzling, or difficult to understand', 'To support or strengthen', 'Not easily understood or explained; open to more than one interpretation']::text[], 0, 'Venerate (শ্রদ্ধা করা, ভক্তি করা) — to regard with great respect; revere. e.g. To venerate the fire chief’s forty years of service, the department held a special banquet.', 'IBA MBA ’23 · 50 Words', true);
insert into public.questions (topic_id, stem, options, correct_index, explanation, source, published)
values ((select id from public.topics where subject_id = (select id from public.subjects where slug = 'english') and slug = 'iba-50-words'), 'The word "SHUN" means —', array['To persistently avoid or reject', 'A lack of harmony or agreement', 'Given to sudden and unpredictable changes of mood or behavior', 'Seeking to promote the welfare of others, especially by donating money']::text[], 0, 'Shun (এড়িয়ে চলা, পরিহার করা) — to persistently avoid or reject. e.g. She has shunned publicity since she retired from acting.', 'IBA MBA ’13 · 50 Words', true);
insert into public.questions (topic_id, stem, options, correct_index, explanation, source, published)
values ((select id from public.topics where subject_id = (select id from public.subjects where slug = 'english') and slug = 'iba-50-words'), 'The word "DERIDE" means —', array['Not able to be seen through; not easily understood', 'To express contempt for; ridicule', 'To avoid telling the truth by not directly answering a question', 'Just begun and so not fully formed or developed']::text[], 1, 'Deride (উপহাস করা, বিদ্রূপ করা) — to express contempt for; ridicule. e.g. The unreasonable supervisor was known to deride his employees on a daily basis.', 'IBA MBA ’12 · 50 Words', true);
insert into public.questions (topic_id, stem, options, correct_index, explanation, source, published)
values ((select id from public.topics where subject_id = (select id from public.subjects where slug = 'english') and slug = 'iba-50-words'), 'The word "EULOGY" means —', array['Willing to take bold risks; or showing a lack of respect', 'Great warmth or intensity of feeling; passion; zeal', 'A speech or writing that praises someone, typically one who has recently died', 'Very clear and easy to understand']::text[], 2, 'Eulogy (স্তুতিবাক্য, প্রশংসা-বক্তৃতা) — a speech or writing that praises someone, typically one who has recently died. e.g. The rabbi’s eulogy was both heartfelt and inspiring.', 'IBA MBA ’05 · 50 Words', true);
insert into public.questions (topic_id, stem, options, correct_index, explanation, source, published)
values ((select id from public.topics where subject_id = (select id from public.subjects where slug = 'english') and slug = 'iba-50-words'), 'The word "LETHARGIC" means —', array['Lacking energy and enthusiasm; sluggish', 'Just begun and so not fully formed or developed', 'To waver between different opinions or actions', 'To make someone less angry or hostile']::text[], 0, 'Lethargic (অলস, শক্তিহীন, নিস্তেজ) — lacking energy and enthusiasm; sluggish. e.g. It’s not uncommon to feel lethargic for weeks or even months after major surgery.', 'IBA BBA ’15 · 50 Words', true);
insert into public.questions (topic_id, stem, options, correct_index, explanation, source, published)
values ((select id from public.topics where subject_id = (select id from public.subjects where slug = 'english') and slug = 'iba-50-words'), 'The word "OBDURATE" means —', array['A lack of harmony or agreement', 'Seeking to promote the welfare of others, especially by donating money', 'Lacking energy and enthusiasm; sluggish', 'Stubbornly refusing to change one’s opinion or course of action']::text[], 3, 'Obdurate (একগুঁয়ে, অনমনীয়) — stubbornly refusing to change one’s opinion or course of action. e.g. The obdurate three-year-old refused to eat any vegetables, no matter how they were prepared.', 'IBA BBA ’21 · 50 Words', true);
insert into public.questions (topic_id, stem, options, correct_index, explanation, source, published)
values ((select id from public.topics where subject_id = (select id from public.subjects where slug = 'english') and slug = 'iba-50-words'), 'The word "PHILANTHROPIC" means —', array['Seeking to promote the welfare of others, especially by donating money', 'Just begun and so not fully formed or developed', 'Using very few words', 'Deserving praise and commendation']::text[], 0, 'Philanthropic (পরোপকারী, মানবহিতৈষী) — seeking to promote the welfare of others, especially by donating money. e.g. The students were grateful to receive financial support from philanthropic organizations that promote education.', 'IBA BBA ’20 · 50 Words', true);
insert into public.questions (topic_id, stem, options, correct_index, explanation, source, published)
values ((select id from public.topics where subject_id = (select id from public.subjects where slug = 'english') and slug = 'iba-50-words'), 'The word "WAVER" means —', array['Excessively talkative, especially about trivial matters', 'To persistently avoid or reject', 'Wastefully extravagant', 'To go back and forth between choices or opinions; be indecisive']::text[], 3, 'Waver (দ্বিধা করা, দোদুল্যমান হওয়া) — to go back and forth between choices or opinions; be indecisive. e.g. Some citizens vote solely along party lines and never waver in their political decisions.', 'IBA BBA ’09, MBA ’11 · 50 Words', true);
insert into public.questions (topic_id, stem, options, correct_index, explanation, source, published)
values ((select id from public.topics where subject_id = (select id from public.subjects where slug = 'english') and slug = 'iba-50-words'), 'The word "BOLSTER" means —', array['A state of physical or mental inactivity; lethargy', 'To support or strengthen', 'A moment of sudden and great revelation or realization', 'The state or quality of being correct or proper; conformity to accepted standards']::text[], 1, 'Bolster (শক্তিশালী করা, জোরদার করা) — to support or strengthen. e.g. The prosecutor worked to find evidence that would bolster her case against the defendant.', 'IBA MBA ’05 · 50 Words', true);
insert into public.questions (topic_id, stem, options, correct_index, explanation, source, published)
values ((select id from public.topics where subject_id = (select id from public.subjects where slug = 'english') and slug = 'iba-50-words'), 'The word "DISSONANCE" means —', array['Great warmth or intensity of feeling; passion; zeal', 'Using very few words', 'A lack of harmony or agreement', 'Stubbornly refusing to change one’s opinion or course of action']::text[], 2, 'Dissonance (অসঙ্গতি, বেসুর, মতবিরোধ) — a lack of harmony or agreement. e.g. The school board’s meeting lasted for hours due to the lengthy debate fueled by dissonance among opinions.', 'IBA MBA ’05 · 50 Words', true);
insert into public.questions (topic_id, stem, options, correct_index, explanation, source, published)
values ((select id from public.topics where subject_id = (select id from public.subjects where slug = 'english') and slug = 'iba-50-words'), 'The word "GARRULOUS" means —', array['A moment of sudden and great revelation or realization', 'Excessively talkative, especially about trivial matters', 'To restrain oneself from doing or enjoying something', 'To confirm or give support to a statement or theory']::text[], 1, 'Garrulous (বাচাল, অতিরিক্ত কথা বলে এমন) — excessively talkative, especially about trivial matters. e.g. The garrulous hair stylist talked to each customer for hours at a time.', 'IBA BBA ’14 · 50 Words', true);
insert into public.questions (topic_id, stem, options, correct_index, explanation, source, published)
values ((select id from public.topics where subject_id = (select id from public.subjects where slug = 'english') and slug = 'iba-50-words'), 'The word "PLIABLE" means —', array['To express contempt for; ridicule', 'Easily bent or shaped; easily influenced; malleable', 'To avoid telling the truth by not directly answering a question', 'Wastefully extravagant']::text[], 1, 'Pliable (নমনীয়; সহজে প্রভাবিত হয় এমন) — easily bent or shaped; easily influenced; malleable. e.g. Children’s moods are often pliable since children are greatly affected by their surroundings.', 'IBA BBA ’19 · 50 Words', true);
insert into public.questions (topic_id, stem, options, correct_index, explanation, source, published)
values ((select id from public.topics where subject_id = (select id from public.subjects where slug = 'english') and slug = 'iba-50-words'), 'The word "OSTENTATION" means —', array['A pretentious or showy display, especially of wealth', 'Excessively talkative, especially about trivial matters', 'Given to sudden and unpredictable changes of mood or behavior', 'Lacking energy and enthusiasm; sluggish']::text[], 0, 'Ostentation (জাঁকজমক, লোকদেখানো আড়ম্বর) — a pretentious or showy display, especially of wealth. e.g. Owning a mansion doesn’t imply ostentation, but traveling exclusively by private jet certainly can.', 'IBA · 50 Words', true);
insert into public.questions (topic_id, stem, options, correct_index, explanation, source, published)
values ((select id from public.topics where subject_id = (select id from public.subjects where slug = 'english') and slug = 'iba-50-words'), 'The word "PREVARICATE" means —', array['To avoid telling the truth by not directly answering a question', 'A lack of harmony or agreement', 'Willing to take bold risks; or showing a lack of respect', 'Using very few words']::text[], 0, 'Prevaricate (সত্য এড়িয়ে যাওয়া, কথা ঘোরানো) — to avoid telling the truth by not directly answering a question. e.g. During the trial, the lead witness was willing to prevaricate in order to protect his friend.', 'IBA · 50 Words', true);

commit;
